        name TEXT NOT NULL, archived INTEGER NOT NULL DEFAULT 0,
        default_priority TEXT NOT NULL DEFAULT 'Normal');
      CREATE TABLE tasks (id INTEGER PRIMARY KEY AUTOINCREMENT,
